<script lang="ts">
  import { buyProperty, closeBusiness, formatCharacterMoney, getMarketPrice, manageBusiness, moveIntoOwnedProperty, rentHome, sellProperty, setPropertyRental, startBusiness, tradeInvestment } from './lib/simulation';
  import type { BusinessType, Character, PropertyType } from './lib/types';
  let { character, onChange }: { character: Character; onChange: (next: Character) => void } = $props();
  const scale = $derived(character.currencyScale ?? 1);
  const properties = $derived(character.properties ?? []);
  const holdings = $derived(character.investments ?? []);
  const businesses = $derived(character.businesses ?? []);
  const economy = $derived(getEconomicConditions(character));
  const rate = (value:number)=>((value*100).toFixed(1)+'%');
  let propertyType = $state<PropertyType>('apartment'); let propertyName = $state(''); let propertyPrice = $state(''); let downPayment = $state(''); let mortgageRate = $state('7'); let mortgageTerm = $state('20'); let primaryResidence = $state(true);
  let rentalType = $state<PropertyType>('apartment'); let annualRent = $state(''); let rentalIncome = $state('');
  let units = $state('1'); let businessType = $state<BusinessType>('retail'); let businessName = $state(''); let businessCapital = $state('');
  let notice = $state('');
  function amount(v:string){const n=Number(v);return Number.isFinite(n)?Math.floor(n):0}
  function run(action:()=>Character,message:string){const next=action();if(next===character){notice='Action unavailable. Check your age, cash, property status, and limits.';return;}onChange(next);notice=message;}
  function purchase(){run(()=>buyProperty(character,propertyType,propertyName,amount(propertyPrice),amount(downPayment),Number(mortgageRate)/100,amount(mortgageTerm),primaryResidence),'Property purchased.');propertyName='';}
  function rent(){run(()=>rentHome(character,rentalType,amount(annualRent)),'Rental home selected.');}
  function listRent(propertyId:string){run(()=>setPropertyRental(character,propertyId,true,amount(rentalIncome)),'Property listed for rent.');}
  function stopRent(propertyId:string){run(()=>setPropertyRental(character,propertyId,false),'Rental listing ended.');}
  function buy(type:'stock-index'|'gold'){run(()=>tradeInvestment(character,type,'buy',amount(units)),'Investment purchased.');}
  function sell(type:'stock-index'|'gold'){run(()=>tradeInvestment(character,type,'sell',amount(units)),'Investment sold.');}
  function openBusiness(){run(()=>startBusiness(character,businessName,businessType,amount(businessCapital)),'Business started.');businessName='';}
</script>
<section class="assets-panel">
  <div class="assets-heading"><div><small>LONG-TERM WEALTH</small><h2>Property & investments</h2></div><span>{properties.length} properties · {businesses.length} businesses</span></div>
  <details><summary>Housing: rent or own</summary>
    <div class="current-home"><small>CURRENT ARRANGEMENT</small><strong>{character.primaryResidenceId ? properties.find((p)=>p.id===character.primaryResidenceId)?.name ?? 'Owned home' : character.rentalHome ? 'Renting · '+character.rentalHome.type : 'Current household arrangement'}</strong>{#if character.rentalHome}<span>{formatCharacterMoney(character,character.rentalHome.annualRent)} annual rent</span>{/if}</div>
    <div class="form-grid"><label>Rent type<select bind:value={rentalType}><option value="apartment">Apartment</option><option value="house">House</option></select></label><label>Annual rent<input type="number" min="1" bind:value={annualRent} placeholder={String(6000*scale)}/></label></div><button onclick={rent} disabled={character.age<18}>Choose rental home</button>
    <h3>Purchase property</h3><div class="form-grid"><label>Property type<select bind:value={propertyType}><option value="apartment">Apartment</option><option value="house">House</option></select></label><label>Name<input bind:value={propertyName} placeholder="My first home"/></label><label>Price<input type="number" min="1" bind:value={propertyPrice} placeholder={String(50000*scale)}/></label><label>Down payment (min 20%)<input type="number" min="1" bind:value={downPayment} placeholder={String(10000*scale)}/></label><label>Mortgage rate %<input type="number" min="0" max="50" step="0.5" bind:value={mortgageRate}/></label><label>Term (years)<input type="number" min="1" max="30" bind:value={mortgageTerm}/></label></div><label class="check"><input type="checkbox" bind:checked={primaryResidence}/> Make this my primary residence</label><button class="primary" onclick={purchase} disabled={character.age<18 || properties.length>=5}>Buy property</button><small class="hint">Mortgages require at least 20% down. Property maintenance is estimated at 1% of value annually. Home values change gradually each year.</small>
    {#each properties as property}<div class="asset-row"><div><strong>{property.name}</strong><small>{property.type} · value {formatCharacterMoney(character,property.marketValue)} · maintenance {formatCharacterMoney(character,property.annualMaintenance)}/yr</small><small>{property.id===character.primaryResidenceId?'Primary residence':property.rentedOut?'Rented out':'Not occupied'}</small></div><div class="asset-actions">{#if property.id!==character.primaryResidenceId && !property.rentedOut}<button onclick={()=>run(()=>moveIntoOwnedProperty(character,property.id),'Moved into property.')}>Move in</button>{/if}<button class="quiet" onclick={()=>run(()=>sellProperty(character,property.id),'Property sold and mortgage settled.')}>Sell</button></div></div>{#if property.id!==character.primaryResidenceId}<div class="form-grid rent-tools"><label>Annual rental income<input type="number" min="1" bind:value={rentalIncome} placeholder={String(8000*scale)}/></label>{#if property.rentedOut}<button onclick={()=>stopRent(property.id)}>Stop renting</button>{:else}<button onclick={()=>listRent(property.id)}>List for rent</button>{/if}</div>{/if}{/each}
  </details>
  <details><summary>Stocks & gold <span>Portfolio {formatCharacterMoney(character,holdings.reduce((sum,h)=>sum+h.units*getMarketPrice(character,h.type),0))}</span></summary>
    <div class="market-grid"><div><small>INDEX FUND · PER UNIT</small><strong>{formatCharacterMoney(character,getMarketPrice(character,'stock-index'))}</strong><span>{holdings.find((h)=>h.type==='stock-index')?.units??0} units</span></div><div><small>GOLD · PER UNIT</small><strong>{formatCharacterMoney(character,getMarketPrice(character,'gold'))}</strong><span>{holdings.find((h)=>h.type==='gold')?.units??0} units</span></div></div>
    <label>Units<input type="number" min="1" max="1000000" bind:value={units}/></label><div class="trade-grid"><div><strong>Index fund</strong><div><button onclick={()=>buy('stock-index')}>Buy</button><button onclick={()=>sell('stock-index')}>Sell</button></div></div><div><strong>Gold</strong><div><button onclick={()=>buy('gold')}>Buy</button><button onclick={()=>sell('gold')}>Sell</button></div></div></div>
    <small class="hint">Simplified simulated market prices move each year. Index funds can rise or fall; gold has different price movement but is not guaranteed protection. Trades use cash and whole units.</small>
  </details>
  <details><summary>Start or manage a business <span>{businesses.length}/3</span></summary>
    {#each businesses as business}<div class="asset-row"><div><strong>{business.name}</strong><small>{business.type} · value {formatCharacterMoney(character,business.valuation)} · performance {business.performance}/100</small><small>Annual operating result is based on business performance.</small></div><div class="asset-actions"><button onclick={()=>run(()=>manageBusiness(character,business.id),'Business managed.')} disabled={character.actionsRemaining<=0}>Manage</button><button class="quiet" onclick={()=>run(()=>closeBusiness(character,business.id),'Business sold.')}>Sell</button></div></div>{/each}
    <div class="form-grid"><label>Business name<input bind:value={businessName} placeholder="My business"/></label><label>Type<select bind:value={businessType}><option value="retail">Retail shop</option><option value="online">Online business</option><option value="cafe">Cafe</option></select></label><label>Startup capital<input type="number" min={1000*scale} bind:value={businessCapital} placeholder={String(5000*scale)}/></label></div><button class="primary" onclick={openBusiness} disabled={character.age<18 || businesses.length>=3}>Start business</button><small class="hint">Annual operating results can be positive or negative. Managing a business costs one action and 1% of invested capital. Selling returns 90% of its current estimated value.</small>
  </details>
  {#if notice}<p class="notice" role="status">{notice}</p>{/if}
</section>
<style>
.assets-panel{border:1px solid rgba(255,255,255,.09);border-radius:16px;padding:16px;margin:16px 0;background:rgba(255,255,255,.02)}.assets-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px}.assets-heading small,.assets-heading span,.hint,.current-home small,.current-home span,.market-grid small,.market-grid span,.asset-row small{color:var(--muted,#999);font-size:11px}.assets-heading h2{font-size:17px;margin:3px 0}.economy-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:10px 0}.economy-strip>div{padding:8px 6px;border-radius:8px;background:rgba(255,255,255,.04);min-width:0}.economy-strip small,.economy-strip strong{display:block}.economy-strip small{font-size:9px;color:var(--muted,#999)}.economy-strip strong{font-size:11px;text-transform:capitalize;margin-top:4px}.economy-strip .recession{color:#ff9b8e}.economy-strip .expansion{color:var(--accent,#43d39e)}.economy-note{font-size:10px;line-height:1.5;color:var(--muted,#999);margin:0 0 10px}.assets-panel details{border-top:1px solid rgba(255,255,255,.08);padding:12px 0}.assets-panel summary{cursor:pointer;font-size:13px;font-weight:700;display:flex;justify-content:space-between;gap:8px}.assets-panel summary span{color:var(--muted,#999);font-weight:500}.current-home,.market-grid>div{padding:12px;background:rgba(255,255,255,.035);border-radius:10px;margin:8px 0}.current-home strong,.current-home span,.market-grid strong,.market-grid span{display:block;margin-top:4px}.current-home strong,.market-grid strong{font-size:14px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}label{display:grid;gap:5px;margin:9px 0;color:var(--muted,#aaa);font-size:11px}input,select{width:100%;min-width:0;padding:10px;border:1px solid rgba(255,255,255,.13);border-radius:8px;background:#171a19;color:#f4f4f4;font:inherit;font-size:12px}.assets-panel button{padding:9px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.06);color:inherit;font-size:11px;font-weight:650}.assets-panel button.primary{background:var(--accent,#43d39e);color:#07150f;border:0}.assets-panel button.quiet{padding:6px 9px}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.asset-row{display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.05)}.asset-row strong,.asset-row small{display:block}.asset-row strong{font-size:12px}.asset-row small{margin-top:3px}.asset-actions{display:flex;flex-direction:column;gap:5px}.rent-tools{align-items:end}.market-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trade-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.trade-grid>div{padding:10px;border:1px solid rgba(255,255,255,.08);border-radius:10px}.trade-grid strong{font-size:12px;display:block;margin-bottom:8px}.trade-grid>div>div{display:flex;gap:6px}.hint{display:block;line-height:1.5;margin:8px 0}.notice{font-size:12px;color:var(--accent,#43d39e)}@media(max-width:460px){.assets-panel{padding:12px}.form-grid{grid-template-columns:1fr}.assets-heading{align-items:flex-start;flex-direction:column}.asset-row{align-items:flex-start}}
</style>